insert into public.site_content(key,value,is_active) values('news',jsonb_build_object('articles',jsonb_build_array(
jsonb_build_object('id','tea-oms','category','NEURODESARROLLO','title','Autismo: diversidad de capacidades y necesidades','excerpt','La OMS explica por qué el espectro es diverso y por qué los apoyos deben adaptarse a cada persona.','read_time','6 min','source','Organización Mundial de la Salud','url','https://www.who.int/news-room/fact-sheets/detail/autism-spectrum-disorders','link_label','Leer fuente oficial'),
jsonb_build_object('id','tea-evaluacion-cdc','category','EVALUACIÓN','title','Cómo se evalúa el autismo','excerpt','El diagnóstico requiere historia del desarrollo, observación profesional y una valoración integral; no existe una prueba médica única.','read_time','5 min','source','CDC','url','https://www.cdc.gov/autism/diagnosis/index.html','link_label','Conocer el proceso'),
jsonb_build_object('id','tea-adultos-cdc','category','ADULTOS','title','Autismo en la vida adulta','excerpt','Las personas adultas también pueden recibir una evaluación, aunque reconstruir la historia temprana puede ser más complejo.','read_time','5 min','source','CDC','url','https://www.cdc.gov/autism/faq/index.html','link_label','Ampliar información'),
jsonb_build_object('id','tea-espanol','category','EN ESPAÑOL','title','Guía básica sobre el trastorno del espectro autista','excerpt','Descripción accesible de características, evaluación y recursos para familias y personas adultas.','read_time','7 min','source','MedlinePlus · NIH','url','https://medlineplus.gov/spanish/autismspectrumdisorder.html','link_label','Leer en español'),
jsonb_build_object('id','tdah-adultos','category','TDAH','title','TDAH en adultos: cuatro aspectos esenciales','excerpt','Atención, inquietud e impulsividad deben ser persistentes, presentarse en varios contextos y afectar la vida cotidiana.','read_time','8 min','source','NIMH','url','https://www.nimh.nih.gov/health/publications/adhd-what-you-need-to-know','link_label','Leer fuente oficial'),
jsonb_build_object('id','tdah-diagnostico','category','EVALUACIÓN','title','Por qué el TDAH necesita una evaluación completa','excerpt','Sueño, estrés, ansiedad, depresión y otras condiciones pueden producir experiencias parecidas y deben considerarse.','read_time','7 min','source','NIMH','url','https://www.nimh.nih.gov/health/publications/attention-deficit-hyperactivity-disorder-what-you-need-to-know','link_label','Conocer la evaluación'),
jsonb_build_object('id','tdah-espanol','category','EN ESPAÑOL','title','TDAH: síntomas, tipos y recursos','excerpt','Información médica revisada sobre inatención, hiperactividad e impulsividad a lo largo de la vida.','read_time','6 min','source','MedlinePlus · NIH','url','https://medlineplus.gov/spanish/attentiondeficithyperactivitydisorder.html','link_label','Leer en español'),
jsonb_build_object('id','tdah-investigacion','category','INVESTIGACIÓN','title','Qué estudia actualmente la ciencia sobre el TDAH','excerpt','Resumen de investigaciones, condiciones concurrentes y recursos públicos actualizados.','read_time','6 min','source','NIMH','url','https://www.nimh.nih.gov/health/topics/attention-deficit-hyperactivity-disorder-adhd','link_label','Explorar recursos'),
jsonb_build_object('id','sueno-memoria','category','APRENDIZAJE','title','Dormir también forma parte del aprendizaje','excerpt','El sueño ayuda a preparar el cerebro para aprender y fortalece recuerdos formados durante el día.','read_time','5 min','source','NIH News in Health','url','https://newsinhealth.nih.gov/2013/04/sleep-it','link_label','Leer artículo'),
jsonb_build_object('id','sueno-salud','category','BIENESTAR','title','Hábitos de sueño para cuidar atención y memoria','excerpt','Dormir suficiente favorece la atención, la memoria y el desempeño cotidiano. Incluye recomendaciones prácticas.','read_time','5 min','source','CDC','url','https://www.cdc.gov/sleep/about/index.html','link_label','Ver recomendaciones'),
jsonb_build_object('id','tea-video','category','VIDEO','title','Comprender el autismo desde fuentes responsables','excerpt','Material audiovisual y educativo para reconocer la diversidad del espectro y evitar mitos.','read_time','Video y recursos','source','CDC Learn the Signs','url','https://www.cdc.gov/ncbddd/actearly/index.html','link_label','Ver recursos y videos'),
jsonb_build_object('id','decidir-consulta','category','ORIENTACIÓN','title','Cuándo conviene solicitar una evaluación profesional','excerpt','Si las experiencias son persistentes, aparecen en varios contextos o afectan estudio, trabajo, relaciones o bienestar, una consulta puede aportar claridad.','read_time','4 min','source','MentesModernas · fuentes OMS, CDC y NIMH','url','https://www.nimh.nih.gov/health/find-help','link_label','Buscar ayuda profesional')
)),true) on conflict(key) do update set value=excluded.value,is_active=true,updated_at=now();
